from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    begin = date.fromisoformat(start)
    parts = rule.split()
    kind, k = parts[0], int(parts[1])
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if kind == "DAILY":
        return [
            (begin + timedelta(days=i * k)).isoformat()
            for i in range(count)
        ]

    result = []

    if kind == "WEEKLY":
        days = sorted(weekdays[wd] for wd in parts[2].split(","))
        week_start = begin - timedelta(days=begin.weekday())

        while True:
            for wd in days:
                candidate = week_start + timedelta(days=wd)
                if candidate >= begin:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            week_start += timedelta(weeks=k)

    if kind == "MONTHLY":
        month_index = begin.year * 12 + begin.month - 1
        n = int(parts[2])
        target_weekday = weekdays[parts[3]] if len(parts) == 4 else None

        while len(result) < count:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, last_day = monthrange(year, month)

            if target_weekday is None:
                day = last_day if n == -1 else n
            elif n == -1:
                last_weekday = (first_weekday + last_day - 1) % 7
                day = last_day - (last_weekday - target_weekday) % 7
            else:
                day = (
                    1 + (target_weekday - first_weekday) % 7
                    + 7 * (n - 1)
                )

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= begin:
                    result.append(candidate.isoformat())

            month_index += k

        return result

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = begin.year

        while len(result) < count:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= begin:
                    result.append(candidate.isoformat())
            year += k

        return result
